const file = (name, bytes) => ({ name, bytes, size: () => bytes });
const dir = (name, ...children) => ({
  name, children,
  add(child) { this.children.push(child); },
  size: () => children.reduce((total, child) => total + child.size(), 0),
});
const tree = dir('root', file('a.txt', 10), dir('sub', file('b.txt', 5)));
